using System.Collections.Generic;
using UnityEngine;
using Entities.Enemies.Helpers;

namespace Entities.Enemies.Data
{
    [CreateAssetMenu(menuName = "Enemies/Enemy Data", fileName = "NewEnemy")]
    public class EnemyConfig : ScriptableObject
    {
        [Header("Core")]
        public string enemyName;
        public int maxHealth;
        public int attackPower;
        public int defensePower;
        public Sprite artwork;
        public List<EnemyAction> actionPattern;

        [Header("Animator (Optional)")]
        [Tooltip("If assigned, this RuntimeAnimatorController will drive the enemy's animation states (Idle/Attack/Hurt/Death). Drag & drop here.")]
        public RuntimeAnimatorController animatorController;

        [Header("Sprite Animations (Lightweight, used if no Animator Controller)")]
        [Tooltip("Looping idle sprite animation for this enemy (optional).")]
        public SpriteAnimation idleAnim;
        [Tooltip("Attack sprite animation for this enemy (optional).")]
        public SpriteAnimation attackAnim;
        [Tooltip("Hurt sprite animation for this enemy (optional).")]
        public SpriteAnimation hurtAnim;
        [Tooltip("Death sprite animation for this enemy (optional).")]
        public SpriteAnimation deathAnim;

        public EnemyData CreateRuntimeInstance()
        {
            var data = new EnemyData();
            data.Initialize(enemyName, maxHealth, attackPower, defensePower);
            data.actionPattern = new List<EnemyAction>(actionPattern);
            data.artwork = artwork;
            // Propagate animator controller and sprite animations
            data.animatorController = animatorController;
            data.idleAnim = idleAnim;
            data.attackAnim = attackAnim;
            data.hurtAnim = hurtAnim;
            data.deathAnim = deathAnim;
            return data;
        }
    }
}

using System;
using System.Collections.Generic;
using UnityEngine;
using Entities.Players.Data;
using Entities.Enemies.Helpers;

[Serializable]
public struct EnemyAction
{
    public EnemyIntent intent;
    public int value;
}

public enum EnemyIntent
{
    Attack,
    Block,
    Heal,
    Buff
}

[Serializable]
public class EnemyData : EntityData
{
    [Header("Core Stats")]
    public int attackPower;           // Base attack power for intents
    public int defensePower;          // Optional, if you have defensive actions

    [Header("Intent System")]
    public EnemyIntent currentIntent; // What the enemy plans to do this turn
    public Sprite intentIcon;         // Icon shown above the enemy (attack, block, buff)
    public string intentText;         // Text like "Attack" or "Buff Self"
    public int intentValue;           // How much damage or block that intent will do

    [Header("Behavior")]
    public List<EnemyAction> actionPattern; // Optional list of possible actions

    [Header("Metadata")]
    public int enemyID;
    public string enemyName;
    public Sprite artwork;                  // Optional portrait or sprite
    public AudioClip attackSFX;             // Optional sound for attack

    [Header("Animator (Optional)")]
    public RuntimeAnimatorController animatorController; // If set, animator-driven states are used

    [Header("Sprite Animations (Lightweight alternative to AnimationClips)")]
    public SpriteAnimation idleAnim;
    public SpriteAnimation attackAnim;
    public SpriteAnimation hurtAnim;
    public SpriteAnimation deathAnim;

    // -------------------------------------------------------
    // Initialization
    // -------------------------------------------------------
    public void Initialize(string name, int maxHealth, int atk, int def)
    {
        enemyName = name;
        attackPower = atk;
        defensePower = def;

        // Call base EntityData initialization
        base.Initialize(name, maxHealth);

        actionPattern = new List<EnemyAction>();
    }

    // -------------------------------------------------------
    // Enemy chooses what to do next
    // -------------------------------------------------------
    public void DecideNextIntent()
    {
        if (actionPattern == null || actionPattern.Count == 0)
        {
            // Default: simple attack
            currentIntent = EnemyIntent.Attack;
            intentValue = attackPower;
            intentText = "Attack";
            return;
        }

        // Randomly select an action from the pattern (Slay the Spire-like)
        int idx = UnityEngine.Random.Range(0, actionPattern.Count);
        var nextAction = actionPattern[idx];
        currentIntent = nextAction.intent;
        intentValue = nextAction.value;
        intentText = nextAction.intent.ToString();
    }

    // -------------------------------------------------------
    // Execute current intent
    // -------------------------------------------------------
    public void ExecuteIntent(PlayerData player)
    {
        if (player == null) return;

        switch (currentIntent)
        {
            case EnemyIntent.Attack:
                player.TakeDamage(intentValue);
                break;

            case EnemyIntent.Block:
                GainBlock(intentValue);  // Now calls inherited method
                break;

            case EnemyIntent.Heal:
                Heal(intentValue);  // Now calls inherited method
                break;

            case EnemyIntent.Buff:
                ApplyStatus("Strength", intentValue);  // Now calls inherited method
                break;
        }
    }

    public bool IsAlive() => isAlive;  // Now uses inherited field
}

using System.Collections.Generic;
using UnityEngine;

namespace Entities.Enemies.Helpers
{
    /// <summary>
    /// Lightweight sprite-based animation data that can be played manually without AnimationClips or Controllers.
    /// More efficient for simple sprite frame sequences.
    /// </summary>
    [CreateAssetMenu(menuName = "Animation/Sprite Animation", fileName = "NewSpriteAnimation")]
    public class SpriteAnimation : ScriptableObject
    {
        [Tooltip("Array of sprite frames to play in sequence.")]
        public List<Sprite> frames = new List<Sprite>();

        [Tooltip("Frames per second (e.g., 12 for classic pixel art feel).")]
        public float frameRate = 12f;

        [Tooltip("Should this animation loop when it reaches the end?")]
        public bool loop = true;

        /// <summary>
        /// Gets the total duration of this animation in seconds.
        /// </summary>
        public float Duration => frames.Count > 0 && frameRate > 0 ? frames.Count / frameRate : 0f;

        /// <summary>
        /// Validates that the animation has at least one frame.
        /// </summary>
        public bool IsValid => frames != null && frames.Count > 0;

        private void OnValidate()
        {
            if (frameRate <= 0f)
            {
                frameRate = 12f;
                Debug.LogWarning($"SpriteAnimation '{name}': frameRate must be > 0. Reset to 12.");
            }

            if (frames == null)
            {
                frames = new List<Sprite>();
            }
        }
    }
}

using UnityEngine;
using System.Collections.Generic;
using GameItems.Cards;

public class PlayerManager : MonoBehaviour
{
    [Header("Data")]
    public PlayerData playerData; // Assign in Inspector

    [Header("Runtime State")]
    public int energy;
    public int maxEnergy;
    public CardManager cardManager = new CardManager();

    // New: runtime combat entity for the player
    public EntityData runtimeEntity { get; private set; }

    private bool _initialized;

    private void Awake()
    {
        if (playerData == null)
        {
            Debug.LogError("PlayerManager: No PlayerData assigned.");
            return;
        }

        InitializeFromData();
    }

    // Runtime API to support code paths that pass PlayerData programmatically
    public void Initialize(PlayerData data)
    {
        playerData = data;
        if (playerData == null)
        {
            Debug.LogError("PlayerManager.Initialize: Provided PlayerData is null.");
            return;
        }
        _initialized = false;
        InitializeFromData();
    }

    private void InitializeFromData()
    {
        if (_initialized) return;
        _initialized = true;

        // Initialize runtime entity from PlayerData config
        runtimeEntity = playerData != null ? playerData.CreateRuntimeEntity() : null;
        if (runtimeEntity == null)
        {
            Debug.LogError("PlayerManager: Failed to create runtime EntityData from PlayerData.");
            return;
        }

        // Energy setup
        maxEnergy = Mathf.Max(1, playerData.maxEnergy > 0 ? playerData.maxEnergy : (playerData.config != null ? playerData.config.defaultMaxEnergy : 3));
        energy = Mathf.Clamp(playerData.baseEnergy > 0 ? playerData.baseEnergy : (playerData.config != null ? playerData.config.defaultBaseEnergy : 3), 0, maxEnergy);

        // Card pools
        cardManager.allCardPool = playerData.usableCards != null && playerData.usableCards.Count > 0
            ? new List<CardData>(playerData.usableCards)
            : new List<CardData>(Resources.LoadAll<CardData>("Cards"));

        foreach (var card in cardManager.allCardPool)
        {
            Debug.Log($"CardManager: Loaded card {card}");
        }

        // Create a starting draw pile (fallback to 10 random cards)
        int startingDeckSize = 10;
        cardManager.drawPile = cardManager.GenerateRandomCards(startingDeckSize);
        cardManager.ShuffleDrawPile();
    }

    public void StartTurn()
    {
        if (runtimeEntity == null) return;

        energy = maxEnergy;
        // Reset block at the start of the turn
        runtimeEntity.block = 0;

        int handSize = playerData.config != null ? Mathf.Max(1, playerData.config.defaultHandSize) : 5;
        for (int i = 0; i < handSize; i++)
            cardManager.DrawCard();
    }

    public bool TryPlayCard(CardData card, ref EntityData target)
    {
        if (runtimeEntity == null || card == null) return false;

        // Simplified energy check (1 per card until card has explicit cost)
        if (energy < 1)
            return false;

        energy -= 1; // TODO: replace with card.energyCost when available
        // cardManager.ApplyCard(card, runtimeEntity, ref target); // TODO: re-fix definition of ApplyCard with actual combat system
        return true;
    }

    public void EndTurn()
    {
        cardManager.DiscardCardPile();
    }
}

using UnityEngine;
using System.Collections.Generic;
using GameItems.Cards;

public class PlayerManager : MonoBehaviour
{
    [Header("Config")]
    [Tooltip("Player configuration asset (ScriptableObject).")]
    public PlayerConfig playerConfig; // Assign in Inspector

    [Header("Runtime State")]
    public PlayerData playerData; // Runtime instance created from config
    public CardManager cardManager = new CardManager();

    private bool _initialized;

    private void Awake()
    {
        if (playerConfig == null)
        {
            Debug.LogError("PlayerManager: No PlayerConfig assigned.");
            return;
        }

        InitializeFromConfig();
    }

    // Runtime API to support code paths that pass PlayerConfig programmatically
    public void Initialize(PlayerConfig config)
    {
        playerConfig = config;
        if (playerConfig == null)
        {
            Debug.LogError("PlayerManager.Initialize: Provided PlayerConfig is null.");
            return;
        }
        _initialized = false;
        InitializeFromConfig();
    }

    private void InitializeFromConfig()
    {
        if (_initialized) return;
        _initialized = true;

        // Create runtime instance from config
        playerData = playerConfig != null ? playerConfig.CreateRuntimeInstance() : null;
        if (playerData == null)
        {
            Debug.LogError("PlayerManager: Failed to create runtime PlayerData from PlayerConfig.");
            return;
        }

        // Energy is now managed by PlayerData itself
        playerData.currentEnergy = playerData.baseEnergy;

        // Card pools
        cardManager.allCardPool = playerData.usableCards != null && playerData.usableCards.Count > 0
            ? new List<CardData>(playerData.usableCards)
            : new List<CardData>(Resources.LoadAll<CardData>("Cards"));

        foreach (var card in cardManager.allCardPool)
        {
            Debug.Log($"CardManager: Loaded card {card}");
        }

        // Create a starting draw pile (fallback to 10 random cards)
        int startingDeckSize = 10;
        cardManager.drawPile = cardManager.GenerateRandomCards(startingDeckSize);
        cardManager.ShuffleDrawPile();
    }

    public void StartTurn()
    {
        if (playerData == null) return;

        // Reset energy and block
        playerData.ResetEnergy();
        playerData.block = 0;

        // Draw hand
        int handSize = playerConfig != null && playerConfig.config != null 
            ? Mathf.Max(1, playerConfig.config.defaultHandSize) 
            : 5;
        for (int i = 0; i < handSize; i++)
            cardManager.DrawCard();
    }

    public bool TryPlayCard(CardData card, ref EntityData target)
    {
        if (playerData == null || card == null) return false;

        // Simplified energy check (1 per card until card has explicit cost)
        if (!playerData.SpendEnergy(1))
            return false;

        // cardManager.ApplyCard(card, playerData, ref target); // TODO: re-fix definition of ApplyCard with actual combat system
        return true;
    }

    public void EndTurn()
    {
        cardManager.DiscardCardPile();
    }
}

using UnityEngine;
using System.Collections.Generic;
using Entities.Enemies.Manager;
using GameItems;

public class BattleManager : MonoBehaviour
{
    public PlayerManager playerManager;
    public EnemyManager enemyManager;
    public RoundManager roundManager;
    [SerializeField] private DeckViewer deckViewer; // Reference to the DeckViewer

    [Header("Config")]
    [Tooltip("Player configuration asset used to initialize the runtime player.")]
    [SerializeField] private PlayerData _playerConfig;

    private void Start()
    {
        if (playerManager == null)
        {
            Debug.LogError("BattleManager: PlayerManager is not assigned.");
            return;
        }

        // 1️⃣ Initialize Player using config asset
        if (_playerConfig != null)
        {
            playerManager.Initialize(_playerConfig);
        }
        else
        {
            Debug.LogWarning("BattleManager: No PlayerData config assigned; using PlayerManager's existing PlayerData.");
        }

        // 2️⃣ Initialize Enemies
        List<EnemyData> enemies = GenerateEnemyWave();
        enemyManager.InitializeEnemies(enemies);

        // 3️⃣ Link Managers
        roundManager.Initialize(playerManager, enemyManager);

        // 4️⃣ Start the first round
        roundManager.StartRound();

        // Build the deck visualization
        if (deckViewer != null)
        {
            deckViewer.SetSource(DeckViewer.Source.Hand);
            deckViewer.Rebuild();
        }
    }

    [SerializeField] private List<EnemyConfig> enemyDatabase;

    private List<EnemyData> GenerateEnemyWave()
    {
        List<EnemyData> wave = new();

        // Example: load 2 random enemies from your database
        for (int i = 0; i < 2; i++)
        {
            var randomEnemy = enemyDatabase[Random.Range(0, enemyDatabase.Count)];
            wave.Add(randomEnemy.CreateRuntimeInstance());
        }

        return wave;
    }
}

